@media (max-width: 900px) {
    .nav { gap: 20px; }
}

@media (max-width: 800px) {
    /* 侧边导航 → 隐藏式抽屉 */
    .ui-side-mask {
        display: block;
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: var(--modal-overlay);
        z-index: 54;
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.3s ease, visibility 0.3s ease;
    }

    .ui-side-mask.show {
        opacity: 1;
        visibility: visible;
    }

    .ui-side-wrap {
        position: fixed;
        left: -230px; /* 用 left 做滑入，transform 会带跑内部 fixed 按钮 */
        top: 0;
        height: 100%;
        width: 230px;
        max-width: 80vw;
        padding: 20px 12px;
        background-color: var(--surface);
        border-right: 1px solid var(--border);
        overflow-y: auto;
        transition: left 0.3s ease;
        z-index: 55;
    }

    .ui-side-wrap.open { left: 0; }

    .ui-side {
        width: 100%;
        flex-direction: column;
        padding: 0;
        gap: 4px;
        transition: none;
    }

    .ui-side-toggle {
        position: fixed;
        left: 14px;
        bottom: 20px;
        width: 44px;
        height: 44px;
        margin: 0;
        border-radius: 50%;
        border: none;
        background-color: var(--primary);
        color: var(--on-primary);
        font-size: 16px;
        z-index: 60;
        box-shadow: 0 4px 14px var(--shadow);
    }

    body.drawer-open { overflow: hidden; }
}

@media (max-width: 640px) {
    .container { padding: 0 16px; }

    .header-inner {
        height: auto;
        min-height: 56px;
        padding: 10px 0;
    }

    .logo-text { display: none; }

    .nav { gap: 14px; }

    .nav a { font-size: 13px; }

    .nav-logo { height: 15px; }

    .theme-select {
        font-size: 12px;
        padding: 5px 24px 5px 10px;
        background-position: right 8px center;
    }

    .modal-box {
        width: auto;
        max-width: 300px;
        margin: 0 20px;
    }
}

@media (max-width: 400px) {
    .nav { gap: 10px; }

    .theme-select { font-size: 11px; padding: 4px 20px 4px 8px; }
}

@media (max-width: 360px) {
    .nav { gap: 6px; }

    .nav-logo { height: 13px; }

    .theme-select {
        font-size: 11px;
        padding: 4px 18px 4px 6px;
        background-position: right 6px center;
    }
}

boxes.code:
:root {
    --primary: #1a1a1a;    /* 主色（按钮/强调） */
    --text-soft: #555555;  /* 正文 */
    --text-muted: #888888; /* 次要文字 */
    --text-faint: #999999; /* 辅助文字 */
    --border: #e5e5e5;     /* 边框 */
    --block: #f5f5f5;      /* 浅灰块背景 */
}

html[data-theme="dark"] {
    --primary: #e8e8e8;
    --text-soft: #b0b0b0;
    --text-muted: #9a9a9a;
    --text-faint: #777777;
    --border: #2e2e2e;
    --block: #1e1e1e;
}

// 点击色块复制色值并弹出提示
document.querySelectorAll('.ui-swatch').forEach(function (sw) {
    sw.addEventListener('click', function () {
        var hex = sw.getAttribute('data-hex');
        navigator.clipboard.writeText(hex).then(function () {
            showToast('已复制 ' + hex);
        });
    });
});

// 主题切换时刷新色块：data-hex-light / data-hex-dark
function refreshSwatches() {
    var t = document.documentElement.getAttribute('data-theme');
    var dark = t ? t === 'dark'
        : window.matchMedia('(prefers-color-scheme: dark)').matches;
    document.querySelectorAll('.ui-swatch').forEach(function (sw) {
        var hex = sw.getAttribute(dark ? 'data-hex-dark' : 'data-hex-light');
        sw.setAttribute('data-hex', hex);
        var p = sw.querySelector('.hex');
        if (p) p.textContent = hex.toUpperCase();
    });
}
refreshSwatches();
document.addEventListener('hts-theme-change', refreshSwatches);

.hero-title {
    font-size: 52px;
    font-weight: bold;
    letter-spacing: 4px;
}

.section-title {
    font-size: 28px;
    font-weight: bold;
    letter-spacing: 2px;
    margin-bottom: 24px;
}

.section-text {
    font-size: 16px;
    color: var(--text-soft);
}

.btn {
    display: inline-block;
    margin-top: 40px;
    padding: 12px 44px;
    background-color: var(--primary);
    color: var(--on-primary);
    text-decoration: none;
    font-size: 15px;
    border-radius: 15px;
    border: 1px solid var(--primary);
    cursor: pointer;
    font-family: inherit;
    transition: background-color 0.25s ease, color 0.25s ease,
                transform 0.15s ease;
}

.btn:hover {
    background-color: var(--bg);
    color: var(--primary);
}

.btn:active { transform: scale(0.97); }

.btn-plain {
    background-color: var(--surface);
    color: var(--primary);
}

.btn-plain:hover {
    background-color: var(--primary);
    color: var(--on-primary);
}

.btn-sm { padding: 8px 24px; font-size: 13px; }

.btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    transform: none;
}

.input, .select, .textarea {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid var(--border);
    border-radius: 10px;
    font-size: 14px;
    font-family: inherit;
    color: var(--text);
    background-color: var(--surface);
    outline: none;
    transition: border-color 0.25s ease, background-color 0.25s ease;
}

.select {
    appearance: none;
    -webkit-appearance: none;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'%3E%3Cpath fill='none' stroke='%23888' stroke-width='1.5' d='M1 1l4 4 4-4'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 14px center;
    padding-right: 34px;
}

.input:focus, .select:focus, .textarea:focus {
    border-color: var(--primary);
}

.input:disabled, .select:disabled, .textarea:disabled {
    background-color: var(--block);
    color: var(--text-faint);
    cursor: not-allowed;
}

.textarea {
    min-height: 88px;
    resize: vertical;
}

input[type="checkbox"] {
    accent-color: var(--primary);
    width: 16px;
    height: 16px;
}

/* 开关 */
.switch {
    position: relative;
    width: 44px; height: 24px;
    border: none;
    border-radius: 12px;
    background-color: var(--border);
    cursor: pointer;
    transition: background-color 0.25s ease;
    flex: none;
}

.switch::after {
    content: "";
    position: absolute;
    top: 2px; left: 2px;
    width: 20px; height: 20px;
    border-radius: 50%;
    background-color: var(--switch-knob);
    box-shadow: 0 1px 3px var(--shadow);
    transition: transform 0.25s ease, background-color 0.25s ease;
}

.switch.on { background-color: var(--primary); }

.switch.on::after {
    transform: translateX(20px);
    background-color: var(--on-primary);
}

document.querySelectorAll('.switch').forEach(function (sw) {
    sw.addEventListener('click', function () {
        sw.classList.toggle('on');
    });
});

.site-card {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 15px;
    padding: 20px;
    text-decoration: none;
    color: inherit;
    transition: border-color 0.25s ease, transform 0.25s ease,
                box-shadow 0.25s ease, background-color 0.3s ease;
}

.site-card:hover {
    border-color: var(--primary);
    transform: translateY(-3px);
    box-shadow: 0 6px 18px var(--shadow);
}

.site-icon {
    width: 44px; height: 44px;
    border-radius: 10px;
    border: 1px solid var(--border);
    flex: none;
    object-fit: contain;
    background-color: var(--surface);
}

.site-letter {
    width: 44px; height: 44px;
    border-radius: 10px;
    background-color: var(--primary);
    color: var(--on-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: bold;
    flex: none;
}

.site-info { min-width: 0; }

.site-name { font-size: 16px; font-weight: bold; }

.site-desc {
    margin-top: 4px;
    font-size: 13px;
    color: var(--text-muted);
    word-break: break-all;
}

.tag {
    display: inline-block;
    padding: 4px 14px;
    border: 1px solid var(--border);
    border-radius: 15px;
    font-size: 13px;
    color: var(--text-soft);
    background-color: var(--surface);
}

.tag-dark {
    background-color: var(--primary);
    border-color: var(--primary);
    color: var(--on-primary);
}

.table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
    background-color: var(--surface);
    text-align: left;
}

/* 表格防溢出：窄屏由外层容器横向滚动 */
.table-wrap {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.table-wrap .table {
    min-width: 480px;
}

.table th, .table td {
    padding: 12px 14px;
    border-bottom: 1px solid var(--border);
}

.table th {
    font-weight: normal;
    font-size: 13px;
    color: var(--text-muted);
}

.table tbody tr {
    transition: background-color 0.2s ease;
}

.table tbody tr:hover {
    background-color: var(--block);
}

.modal-mask {
    visibility: hidden;
    opacity: 0;
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background-color: var(--modal-overlay);
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: opacity 0.25s ease, visibility 0.25s ease;
}

.modal-mask.show {
    visibility: visible;
    opacity: 1;
}

.modal-box {
    position: relative;
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 15px;
    padding: 36px 40px 30px;
    text-align: center;
    width: 300px;
    transform: scale(0.94);
    transition: transform 0.25s ease, background-color 0.3s ease,
                border-color 0.3s ease;
}

.modal-mask.show .modal-box { transform: scale(1); }

.modal-close {
    position: absolute;
    top: 10px; right: 14px;
    background: none;
    border: none;
    font-size: 24px;
    line-height: 1;
    color: var(--text-faint);
    cursor: pointer;
    font-family: inherit;
    transition: color 0.25s ease, transform 0.25s ease;
}

