}

/* 可拖动进度条：拖动时实时跟随，取消过渡避免迟滞 */
.progress-drag {
    cursor: pointer;
    touch-action: none;
    overflow: visible; /* 让小球能超出 6px 轨道显示 */
}

.progress-drag .progress-bar {
    transition: none;
    position: relative;
}

/* 拖动手柄小球：跟随填充末端，悬停/拖动时显示 */
.progress-thumb {
    position: absolute;
    right: -8px;
    top: 50%;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background-color: var(--primary);
    border: 2px solid var(--bg);
    box-sizing: border-box;
    transform: translateY(-50%) scale(0.4);
    opacity: 0;
    transition: transform 0.2s ease, opacity 0.2s ease;
    pointer-events: none;
}

.progress-drag:hover .progress-thumb,
.progress-drag.dragging .progress-thumb {
    transform: translateY(-50%) scale(1);
    opacity: 1;
}

.progress-drag.dragging .progress-thumb {
    transform: translateY(-50%) scale(1.2);
}

.divider {
