    border-color: var(--primary);
}

/* 展开后才显示复制按钮 */
.code-box.expanded .code-copy {
    opacity: 1;
    pointer-events: auto;
}

.code-box pre {
    margin: 0;
    padding: 0 18px;
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: max-height 0.3s ease, opacity 0.25s ease, padding 0.3s ease;
}

.code-box.expanded pre {
    max-height: var(--code-max-height); /* 超长时框内竖向滚动，不撑长页面 */
    padding: 16px 18px;
    opacity: 1;
    overflow: auto;
}

.code-box code {
    display: block;
    font-family: "Consolas", "Monaco", "Courier New", monospace;
    font-size: 13px;
    line-height: 1.6;
    color: var(--code-text);
    white-space: pre;
    counter-reset: line;
}

/* 代码行（行号由 CSS 计数器生成，横向滚动时固定在左侧） */
.code-line {
    display: block;
    counter-increment: line;
}

.code-line::before {
    content: counter(line);
    position: sticky;
    left: 0;
    display: inline-block;
    width: 2.2em;
    padding-right: 12px;
    margin-right: 12px;
    text-align: right;
    color: var(--text-faint);
    background-color: var(--code-bg);
    border-right: 1px solid var(--border);
    user-select: none;
}

// 按行包裹（配合 CSS 计数器显示行号）
document.querySelectorAll('.code-box pre > code').forEach(function (code) {
    var lines = code.textContent.split('\n');
    code.textContent = '';
    lines.forEach(function (line) {
        var s = document.createElement('span');
        s.className = 'code-line';
        s.appendChild(document.createTextNode(line));
        code.appendChild(s);
    });
});

// 代码框展开/收起
document.querySelectorAll('.code-box').forEach(function (box) {
    var head = box.querySelector('.code-box-head');
    if (!head) return;
    head.addEventListener('click', function (e) {
        // 点击复制按钮不触发展开/收起
        if (e.target.classList.contains('code-copy')) return;
        box.classList.toggle('expanded');
    });
});

// 复制按钮（逐行取值拼回纯代码，不含行号；成功后短暂显示"已复制"）
document.querySelectorAll('.code-copy').forEach(function (btn) {
    btn.addEventListener('click', function () {
        var rows = btn.closest('.code-box').querySelectorAll('.code-line');
        var code = Array.prototype.map.call(rows, function (l) {
            return l.textContent;
        }).join('\n');
        function done() {
            var old = btn.textContent;
            btn.textContent = '已复制';
            setTimeout(function () { btn.textContent = old; }, 1200);
        }
        function fallback() {
            var t = document.createElement('textarea');
            t.value = code;
            document.body.appendChild(t);
            t.select();
            document.execCommand('copy');
            document.body.removeChild(t);
            done();
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(code).then(done, fallback);
        } else {
            fallback();
        }
    });
});

