    position: absolute;
    left: 6px;
    top: 4px;
    bottom: 4px;
    width: 1px;
    background: var(--border);
}

.timeline-item {
    position: relative;
    padding-bottom: 18px;
}

.timeline-item:last-child {
    padding-bottom: 0;
}

.timeline-item::before {
    content: '';
    position: absolute;
    left: -19px;
    top: 4px;
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--surface);
    border: 1px solid var(--primary);
}

.timeline-item .time {
    font-size: 12px;
    color: var(--text-faint);
}

.timeline-item .tl-title {
    font-size: 14px;
    color: var(--text);
    margin: 2px 0;
}

.timeline-item .tl-desc {
    font-size: 13px;
    color: var(--text-soft);
}

.avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--primary);
    color: var(--on-primary);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    overflow: hidden;
    flex: 0 0 auto;
}

.avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar.sm {
    width: 28px;
    height: 28px;
    font-size: 12px;
}

.avatar.lg {
    width: 56px;
    height: 56px;
    font-size: 20px;
}

.avatar.square {
    border-radius: 10px;
}

.avatar-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.avatar-group {
    display: flex;
}

.avatar-group .avatar {
    margin-left: -10px;
    border: 2px solid var(--bg);
}

.avatar-group .avatar:first-child {
    margin-left: 0;
}

.skeleton {
    position: relative;
    background: var(--block);
    border-radius: 8px;
    animation: hts-skeleton 1.2s ease-in-out infinite;
}

@keyframes hts-skeleton {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.45; }
}

.skeleton-line {
    height: 14px;
    margin-bottom: 10px;
}

.skeleton-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
}

.skeleton-block {
    height: 120px;
}

.alert {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 12px 16px;
    font-size: 13px;
    color: var(--text-soft);
    background: var(--block);
}

.alert .alert-title {
    font-weight: bold;
    color: var(--text);
}

.alert.strong {
    background: var(--surface);
    border-left: 3px solid var(--primary);
    border-radius: 0 10px 10px 0;
}

.alert.dark {
    background: var(--primary);
    border-color: var(--primary);
    color: var(--on-primary);
}

.alert.dark .alert-title {
    color: var(--on-primary);
}

.empty {
    text-align: center;
    padding: 48px 20px;
    color: var(--text-muted);
    font-size: 13px;
}

.empty .empty-icon {
    width: 56px;
    height: 56px;
    margin: 0 auto 14px;
    border: 1px solid var(--border);
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    color: var(--text-faint);
    background: var(--block);
}

.empty .empty-title {
    color: var(--text);
    font-size: 14px;
    margin-bottom: 4px;
}

.spinner {
    display: inline-block;
    width: 22px;
    height: 22px;
    border: 2px solid var(--border);
    border-top-color: var(--primary);
    border-radius: 50%;
    animation: hts-spin 0.8s linear infinite;
    vertical-align: -6px;
}

.spinner.sm {
    width: 16px;
    height: 16px;
    border-width: 2px;
    vertical-align: -3px;
}

.spinner.lg {
    width: 32px;
    height: 32px;
    border-width: 3px;
    vertical-align: -8px;
}

@keyframes hts-spin {
    to { transform: rotate(360deg); }
}

[data-tip] {
    position: relative;
}

[data-tip]::after {
    content: attr(data-tip);
    position: absolute;
    bottom: calc(100% + 8px);
    left: 50%;
    transform: translateX(-50%) scale(0.92);
    background: var(--primary);
    color: var(--on-primary);
    font-size: 12px;
    line-height: 1.4;
    padding: 6px 10px;
    border-radius: 8px;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.15s ease, transform 0.15s ease;
    z-index: 10;
}

[data-tip]:hover::after,
[data-tip]:focus-visible::after {
    opacity: 1;
    transform: translateX(-50%) scale(1);
}

[data-tip].tip-bottom::after {
    bottom: auto;
    top: calc(100% + 8px);
}

.dropdown {
    position: relative;
    display: inline-block;
}

.dropdown-menu {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    min-width: 150px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 6px;
    box-shadow: 0 8px 24px var(--shadow);
    display: none;
    z-index: 20;
}

.dropdown.open .dropdown-menu {
    display: block;
}

.dropdown-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 8px 10px;
    font-size: 13px;
    border: none;
    background: transparent;
    border-radius: 7px;
    cursor: pointer;
    color: var(--text-soft);
}

.dropdown-item:hover {
    background: var(--block);
    color: var(--text);
}

.dropdown-divider {
    height: 1px;
    background: var(--border);
    margin: 6px 0;
}

.segmented {
    display: inline-flex;
    background: var(--block);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 3px;
    gap: 3px;
}

.segmented button {
    border: none;
    background: transparent;
    padding: 6px 16px;
    font-size: 13px;
    border-radius: 9px;
    color: var(--text-muted);
    cursor: pointer;
}

.segmented button.active {
    background: var(--surface);
    color: var(--text);
    font-weight: bold;
    box-shadow: 0 1px 4px var(--shadow);
}

.list-group {
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--surface);
    overflow: hidden;
}

.list-group-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    font-size: 14px;
    color: var(--text);
}

.list-group-item + .list-group-item {
    border-top: 1px solid var(--border);
}

.list-group-item:hover {
    background: var(--block);
}

.list-group-item .lg-sub {
    margin-left: auto;
    font-size: 12px;
    color: var(--text-muted);
    flex: 0 0 auto;
}

.list-group-item .lg-text {
    min-width: 0;
}

.list-group-item .lg-desc {
    display: block;
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 2px;
}

css.css:
:root {
    --bg: #ffffff;
    --surface: #ffffff;
    --block: #f5f5f5;
    --border: #e5e5e5;
    --text: #1a1a1a;
    --text-soft: #555555;
    --text-muted: #888888;
    --text-faint: #999999;
    --primary: #1a1a1a;
    --on-primary: #ffffff;
    --footer-bg: #1a1a1a;
    --footer-text: #ffffff;
    --footer-muted: #999999;
    --shadow: rgba(0, 0, 0, 0.06);
    --modal-overlay: rgba(0, 0, 0, 0.5);
    --switch-knob: #ffffff;
    --code-bg: #f5f5f5;
    --code-text: #555555;
    --code-max-height: 320px;
}

html[data-theme="light"] {
    --bg: #ffffff;
    --surface: #ffffff;
    --block: #f5f5f5;
    --border: #e5e5e5;
    --text: #1a1a1a;
    --text-soft: #555555;
    --text-muted: #888888;
    --text-faint: #999999;
    --primary: #1a1a1a;
    --on-primary: #ffffff;
    --footer-bg: #1a1a1a;
    --footer-text: #ffffff;
    --footer-muted: #999999;
    --shadow: rgba(0, 0, 0, 0.06);
    --modal-overlay: rgba(0, 0, 0, 0.5);
    --switch-knob: #ffffff;
    --code-bg: #f5f5f5;
    --code-text: #555555;
}

html[data-theme="dark"] {
    --bg: #141414;
    --surface: #1c1c1c;
    --block: #1e1e1e;
    --border: #2e2e2e;
    --text: #e8e8e8;
    --text-soft: #b0b0b0;
    --text-muted: #9a9a9a;
    --text-faint: #777777;
    --primary: #e8e8e8;
    --on-primary: #141414;
    --footer-bg: #0d0d0d;
    --footer-text: #e8e8e8;
    --footer-muted: #888888;
    --shadow: rgba(0, 0, 0, 0.35);
    --modal-overlay: rgba(0, 0, 0, 0.7);
    --switch-knob: #f0f0f0;
    --code-bg: #1e1e1e;
    --code-text: #b0b0b0;
}

@media (prefers-color-scheme: dark) {
    html:not([data-theme]) {
        --bg: #141414;
        --surface: #1c1c1c;
        --block: #1e1e1e;
        --border: #2e2e2e;
        --text: #e8e8e8;
        --text-soft: #b0b0b0;
        --text-muted: #9a9a9a;
        --text-faint: #777777;
        --primary: #e8e8e8;
        --on-primary: #141414;
        --footer-bg: #0d0d0d;
        --footer-text: #e8e8e8;
        --footer-muted: #888888;
        --shadow: rgba(0, 0, 0, 0.35);
        --modal-overlay: rgba(0, 0, 0, 0.7);
        --switch-knob: #f0f0f0;
        --code-bg: #1e1e1e;
        --code-text: #b0b0b0;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

section[id], .ui-block {
    scroll-margin-top: 88px;
}

body {
    font-family: "Microsoft YaHei", "PingFang SC", Arial, sans-serif;
    color: var(--text);
    background-color: var(--bg);
    line-height: 1.7;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.container {
    max-width: 1080px;
    margin: 0 auto;
    padding: 0 24px;
}

.only-dark { display: none; }
html[data-theme="dark"] .only-dark { display: block; }
html[data-theme="dark"] .only-light { display: none; }
@media (prefers-color-scheme: dark) {
    html:not([data-theme]) .only-dark { display: block; }
    html:not([data-theme]) .only-light { display: none; }
}

.header {
    background-color: var(--bg);
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    z-index: 10;
    transition: background-color 0.3s ease, border-color 0.3s ease;
}

.header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 64px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 10px;
    flex: none;
    margin-left: 12px;
}

.logo-icon {
    width: 28px;
    height: 28px;
}

img.logo-dark { display: none; }
html[data-theme="dark"] .logo-light { display: none; }
html[data-theme="dark"] .logo-dark { display: inline-block; }
@media (prefers-color-scheme: dark) {
    html:not([data-theme]) .logo-light { display: none; }
    html:not([data-theme]) .logo-dark { display: inline-block; }
}

.logo-text {
    font-size: 18px;
    font-weight: bold;
    letter-spacing: 1px;
}

.nav {
    display: flex;
    align-items: center;
    gap: 28px;
}

.nav a {
    position: relative;
    color: var(--text);
    text-decoration: none;
    font-size: 15px;
    white-space: nowrap;
    flex: none;
    transition: color 0.25s ease;
}

.nav a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -4px;
    width: 100%;
    height: 1px;
    background-color: var(--primary);
    transform: scaleX(0);
    transition: transform 0.25s ease;
}

.nav a:hover {
    color: var(--text-muted);
}

.nav a:hover::after {
    transform: scaleX(1);
}

.nav a.nav-img {
    display: flex;
    align-items: center;
}

.nav-logo {
    height: 17px;
    width: auto;
    display: block;
}

.nav a.nav-img::after {
    left: 20%;
    width: 60%;
    bottom: -8px;
}

.theme-select {
    appearance: none;
    -webkit-appearance: none;
    flex: none;
    padding: 6px 28px 6px 12px;
    font-size: 13px;
    font-family: inherit;
    color: var(--text);
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    cursor: pointer;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'%3E%3Cpath fill='none' stroke='%23888' stroke-width='1.5' d='M1 1l4 4 4-4'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 10px center;
    transition: border-color 0.25s ease, background-color 0.25s ease;
}

.theme-select:hover,
.theme-select:focus {
    border-color: var(--primary);
    outline: none;
}

.ui-side-wrap {
    position: sticky;
    top: 88px;
    flex: none;
}

.ui-side-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    margin-bottom: 8px;
    margin-left: auto;
    background: none;
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-soft);
    font-size: 14px;
    cursor: pointer;
    transition: color 0.2s ease, border-color 0.2s ease;
}

.ui-side-toggle:hover {
    color: var(--primary);
    border-color: var(--primary);
}

.ui-side {
    width: 180px;
    padding: 12px 0 32px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    overflow: hidden;
    transition: width 0.3s ease, opacity 0.3s ease;
}

.ui-side.collapsed {
    width: 0;
    opacity: 0;
}

.ui-side a {
    padding: 8px 14px;
    font-size: 14px;
    color: var(--text-soft);
    text-decoration: none;
    border-radius: 10px;
    white-space: nowrap;
    transition: color 0.2s ease, background-color 0.2s ease;
}

.ui-side a:hover {
    color: var(--primary);
    background-color: var(--block);
}

.ui-side a.active {
    color: var(--on-primary);
    background-color: var(--primary);
}

.btn {
    display: inline-block;
    padding: 12px 44px;
    background-color: var(--primary);
    color: var(--on-primary);
    text-decoration: none;
    font-size: 15px;
    border-radius: 15px;
    border: 1px solid var(--primary);
    cursor: pointer;
    font-family: inherit;
    transition: background-color 0.25s ease, color 0.25s ease, transform 0.15s ease;
}

.btn:hover {
    background-color: var(--bg);
    color: var(--primary);
}

.btn:active {
    transform: scale(0.97);
}

.btn-plain {
    background-color: var(--surface);
    color: var(--primary);
}

.btn-plain:hover {
    background-color: var(--primary);
    color: var(--on-primary);
}

.btn-sm {
    padding: 8px 24px;
    font-size: 13px;
}

.btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    transform: none;
}

.input,
.select,
.textarea {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid var(--border);
    border-radius: 10px;
    font-size: 14px;
    font-family: inherit;
    color: var(--text);
    background-color: var(--surface);
    outline: none;
    transition: border-color 0.25s ease, background-color 0.25s ease;
}

.select {
    appearance: none;
    -webkit-appearance: none;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'%3E%3Cpath fill='none' stroke='%23888' stroke-width='1.5' d='M1 1l4 4 4-4'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 14px center;
    padding-right: 34px;
}

.input:focus,
.select:focus,
.textarea:focus {
    border-color: var(--primary);
}

.input:disabled,
.select:disabled,
.textarea:disabled {
    background-color: var(--block);
    color: var(--text-faint);
    cursor: not-allowed;
}

.textarea {
    min-height: 88px;
    resize: vertical;
}

input[type="checkbox"] {
    accent-color: var(--primary);
    width: 16px;
    height: 16px;
}

.switch {
    position: relative;
    width: 44px;
    height: 24px;
    border: none;
    border-radius: 12px;
    background-color: var(--border);
    cursor: pointer;
    transition: background-color 0.25s ease;
    flex: none;
}

.switch::after {
    content: "";
    position: absolute;
    top: 2px;
    left: 2px;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background-color: var(--switch-knob);
    box-shadow: 0 1px 3px var(--shadow);
    transition: transform 0.25s ease, background-color 0.25s ease;
}

.switch.on {
    background-color: var(--primary);
}

.switch.on::after {
    transform: translateX(20px);
    background-color: var(--on-primary);
}

.site-card {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 15px;
    padding: 20px;
    text-decoration: none;
    color: inherit;
    transition: border-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease, background-color 0.3s ease;
}

.site-card:hover {
    border-color: var(--primary);
    transform: translateY(-3px);
    box-shadow: 0 6px 18px var(--shadow);
}

.site-icon {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    border: 1px solid var(--border);
    flex: none;
    object-fit: contain;
    background-color: var(--surface);
}

.site-letter {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background-color: var(--primary);
    color: var(--on-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: bold;
    flex: none;
}

.site-info { min-width: 0; }
.site-name { font-size: 16px; font-weight: bold; }

.site-desc {
    margin-top: 4px;
    font-size: 13px;
    color: var(--text-muted);
    word-break: break-all;
}

.tag {
    display: inline-block;
    padding: 4px 14px;
    border: 1px solid var(--border);
    border-radius: 15px;
    font-size: 13px;
    color: var(--text-soft);
    background-color: var(--surface);
}

.tag-dark {
    background-color: var(--primary);
    border-color: var(--primary);
    color: var(--on-primary);
}

.table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
    background-color: var(--surface);
    text-align: left;
}

.table-wrap {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.table-wrap .table {
    min-width: 480px;
}

.table th,
.table td {
    padding: 12px 14px;
    border-bottom: 1px solid var(--border);
}

.table th {
    font-weight: normal;
    font-size: 13px;
    color: var(--text-muted);
}

.table tbody tr {
    transition: background-color 0.2s ease;
}

.table tbody tr:hover {
    background-color: var(--block);
}

.divider {
    height: 1px;
    border: none;
    background-color: var(--border);
}

.progress {
    height: 6px;
    background-color: var(--block);
    border-radius: 3px;
    overflow: hidden;
}

.progress-bar {
    height: 100%;
    width: 0;
    background-color: var(--primary);
    border-radius: 3px;
    transition: width 0.6s ease;
}

.progress-drag {
    cursor: pointer;
    touch-action: none;
    overflow: visible; /* 让小球能超出 6px 轨道显示 */
}

.progress-drag .progress-bar {
    transition: none;
    position: relative;
}

.progress-thumb {
    position: absolute;
    right: -8px;
    top: 50%;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background-color: var(--primary);
    border: 2px solid var(--bg);
    box-sizing: border-box;
    transform: translateY(-50%) scale(0.4);
    opacity: 0;
    transition: transform 0.2s ease, opacity 0.2s ease;
    pointer-events: none;
}

.progress-drag:hover .progress-thumb,
.progress-drag.dragging .progress-thumb {
    transform: translateY(-50%) scale(1);
    opacity: 1;
}

.progress-drag.dragging .progress-thumb {
    transform: translateY(-50%) scale(1.2);
}

.modal-mask {
    visibility: hidden;
    opacity: 0;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: var(--modal-overlay);
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: opacity 0.25s ease, visibility 0.25s ease;
}

.modal-mask.show {
    visibility: visible;
    opacity: 1;
}

.modal-box {
    position: relative;
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 15px;
    padding: 36px 40px 30px;
    text-align: center;
    width: 300px;
    transform: scale(0.94);
    transition: transform 0.25s ease, background-color 0.3s ease, border-color 0.3s ease;
}

.modal-mask.show .modal-box {
    transform: scale(1);
}

.modal-close {
    position: absolute;
    top: 10px;
    right: 14px;
    background: none;
    border: none;
    font-size: 24px;
    line-height: 1;
    color: var(--text-faint);
    cursor: pointer;
    font-family: inherit;
    transition: color 0.25s ease, transform 0.25s ease;
}

.modal-close:hover {
    color: var(--primary);
    transform: rotate(90deg);
}

.modal-title {
    font-size: 20px;
    font-weight: bold;
    letter-spacing: 2px;
    margin-bottom: 20px;
}

.toast {
    position: fixed;
    left: 50%;
    bottom: 32px;
    transform: translate(-50%, 16px);
    background-color: var(--primary);
    color: var(--on-primary);
    padding: 10px 26px;
    border-radius: 15px;
    font-size: 14px;
    opacity: 0;
    visibility: hidden;
    z-index: 200;
    transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s ease;
}

.toast.show {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, 0);
}

.code-box {
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
    margin-top: 16px;
    background-color: var(--code-bg);
}

.code-box-head {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 40px 8px 14px;
    background-color: var(--surface);
    border-bottom: 1px solid var(--border);
    cursor: pointer;
    user-select: none;
    transition: background-color 0.3s ease;
}

.code-box-head:hover {
    background-color: var(--block);
}

.code-box-head::after {
    content: "▶";
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 10px;
    color: var(--text-faint);
    transition: transform 0.25s ease;
}

.code-box.expanded .code-box-head::after {
    transform: translateY(-50%) rotate(90deg);
}

.code-box-lang {
    font-size: 12px;
    color: var(--text-muted);
    font-family: "Consolas", "Monaco", monospace;
    letter-spacing: 0.5px;
}

.code-copy {
    padding: 4px 12px;
    font-size: 12px;
    font-family: inherit;
    color: var(--text-soft);
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.code-copy:hover {
    color: var(--primary);
    border-color: var(--primary);
}

.code-box.expanded .code-copy {
    opacity: 1;
    pointer-events: auto;
}

.code-box pre {
    margin: 0;
    padding: 0 18px;
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: max-height 0.3s ease, opacity 0.25s ease, padding 0.3s ease;
}

.code-box.expanded pre {
    max-height: var(--code-max-height);
    padding: 16px 18px;
    opacity: 1;
    overflow: auto;
}

.code-box code {
    display: block;
    font-family: "Consolas", "Monaco", "Courier New", monospace;
    font-size: 13px;
    line-height: 1.6;
    color: var(--code-text);
    white-space: pre;
    counter-reset: line;
}

.code-line {
    display: block;
    counter-increment: line;
}

.code-line::before {
    content: counter(line);
    position: sticky;
    left: 0;
    display: inline-block;
    width: 2.2em;
    padding-right: 12px;
    margin-right: 12px;
    text-align: right;
    color: var(--text-faint);
    background-color: var(--code-bg);
    border-right: 1px solid var(--border);
    user-select: none;
}

.footer {
    background-color: var(--footer-bg);
    color: var(--footer-text);
    text-align: center;
    padding: 32px 0;
    font-size: 14px;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.footer-site {
    margin-top: 6px;
